@triton.jit
def _morse_t_20000000000000(pos_ptr, cell_ptr, bat_ptr, s_ptr, idx_ptr, d_ptr, al_ptr, r0_ptr, e, m, n_terms, tiny, DT: tl.constexpr, HAS_CELL: tl.constexpr, pos_ptr_t):
    """Tangent of ``_morse`` along the arguments pos_ptr."""
    a = tl.load(idx_ptr + e, mask=m, other=0).to(tl.int64)
    b = tl.load(idx_ptr + n_terms + e, mask=m, other=0).to(tl.int64)
