        g2x += es * (-p2x / DL + f * A * n2x)
        g2x_t += es_t * (-p2x / DL + f * A * n2x) + es * (-p2x_t / DL - -p2x / DL * DL_t / DL + ((f_t * A + f * A_t) * n2x + f * A * n2x_t))
